-- New Setup UI Strings

L["POPUP_COMPANION_WARNING_TEXT"] = "|cffffd100Offhand Companion %s ist erforderlich, aber WoW verwendet keine bestätigte Monitorerweiterung.|r\n\nÖffne Companion, wähle deine Monitore und den Mainhand-Monitor aus und klicke auf WoW jetzt erweitern. Falls WoW bereits geöffnet war, gib danach /reload ein.\n\nLade die passende Companion-Version hier herunter:"
L["POPUP_COMPANION_HANDOFF_TEXT"] = "|cffffd100Offhand konnte die aktuelle Monitorerweiterung nicht bestätigen.|r\n\nDeine Addon- und Companion-Versionen sind möglicherweise bereits korrekt. Offhand hat für dieses WoW-Fenster keinen passenden Anzeige-Layout-Schnappschuss geladen.\n\nÖffne Companion und klicke auf Span WoW Now. Falls WoW bereits lief, gib danach einmal /reload ein.\n\nDu musst Companion nur erneut herunterladen, wenn Companion meldet, dass deine Version inkompatibel ist."
L["POPUP_COMPANION_TOPOLOGY_TEXT"] = "|cffffd100Die gespeicherte Bildschirmanordnung passt nicht mehr zum WoW-Fenster.|r\n\nAddon- und Companion-Version können bereits stimmen. Öffne |cffffd100Companion|r, prüfe Bildschirme und Mainhand und klicke auf |cffffd100Span WoW Now|r.\n\nNutze in WoW einmal |cffffd100/reload|r, falls es beim Erweitern bereits lief."
L["POPUP_COMPANION_VERSION_TEXT"] = "|cffffd100Companion-Versionskonflikt|r\n\nDieses Anzeige-Layout wurde mit Companion %s erstellt, aber dieses Addon benötigt %s. Aktualisiere Companion, erweitere WoW erneut und gib /reload ein.\n\nKopiere die offizielle Download-Adresse unten:"
L["POPUP_BTN_GOT_IT"] = "Verstanden"
L["POPUP_WELCOME_WARNING_TEXT"] = "|cffffd100Willkommen bei Offhand!|r\n\nUm diese Zwei-Monitor-Oberfläche zu nutzen, muss dein World of Warcraft-Fenster über zwei Bildschirme gestreckt sein. Derzeit läuft das Spiel nur auf einem Bildschirm.\n\nWir empfehlen dringend die |cff00ff00Offhand Companion App|r (Windows .exe), um WoW automatisch pixelgenau und randlos über deine Monitore zu strecken.\n\nSobald das Spiel auf beiden Bildschirmen angezeigt wird, klicke auf „Assistent starten“, um die Oberfläche zu kalibrieren."
L["POPUP_BTN_GET_APP"] = "App holen (Link kopieren)"
L["POPUP_BTN_LAUNCH_WIZARD"] = "Assistent starten"
L["POPUP_BTN_IGNORE"] = "Ignorieren"
L["WIZARD_WELCOME_TEXT"] = "|cffffd100Willkommen bei Offhand!|r Dein World of Warcraft-Fenster ist jetzt über deine Monitore gestreckt.\n\nOffhand teilt deine Benutzeroberfläche ideal auf: Das 3D-Spiel erscheint auf deinem Hauptmonitor, während der zweite Bildschirm eine aufgeräumte Arbeitsfläche für Karten, Taschen und Texte bietet.\n\nKlicke unten auf |cff00ff00Automatisch einrichten|r, um die Kalibrierung direkt durchzuführen."

