L["BTN_REMEMBER_CURRENT_WINDOW_TIP_DESC"] = "Bestätigt, dass das aktuelle WoW-Fenster korrekt positioniert ist. Offhand verwendet das Layout nach einem Neustart bei passender Größe erneut."
L["MANUAL_CANVAS_DEFAULT_NAME"] = "Gespeicherte Arbeitsfläche"
